import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    total_rev_tw = df['Revenue_TW'].sum(skipna=True)
    total_rev_lw = df['Revenue_LW'].sum(skipna=True)
    total_rev_ly = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else None
    total_units_tw = df['Units_TW'].sum(skipna=True)
    total_units_lw = df['Units_LW'].sum(skipna=True)
    total_orders_tw = df['Orders_TW'].sum(skipna=True)
    total_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(total_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    if pd.notna(total_rev_lw):
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LW",
            "value": round(float(total_rev_lw), 2),
            "formula": "sum(Revenue_LW)"
        })
    if total_rev_ly is not None and pd.notna(total_rev_ly):
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(total_rev_ly), 2),
            "formula": "sum(Revenue_LY)"
        })

    if pd.notna(total_rev_lw) and total_rev_lw != 0:
        wow_total = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly is not None and pd.notna(total_rev_ly) and total_rev_ly != 0:
        yoy_total = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    if pd.notna(total_units_tw):
        facts.append({
            "entity": "TOTAL", "metric": "units", "period": "TW",
            "value": round(float(total_units_tw), 2),
            "formula": "sum(Units_TW)"
        })
    if pd.notna(total_units_lw):
        facts.append({
            "entity": "TOTAL", "metric": "units", "period": "LW",
            "value": round(float(total_units_lw), 2),
            "formula": "sum(Units_LW)"
        })
    if pd.notna(total_orders_tw):
        facts.append({
            "entity": "TOTAL", "metric": "orders", "period": "TW",
            "value": round(float(total_orders_tw), 2),
            "formula": "sum(Orders_TW)"
        })
    if pd.notna(total_orders_lw):
        facts.append({
            "entity": "TOTAL", "metric": "orders", "period": "LW",
            "value": round(float(total_orders_lw), 2),
            "formula": "sum(Orders_LW)"
        })

    # ---------- TOP 5 ENTITIES BY REVENUE_TW ----------
    top5 = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top5.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "TW",
            "value": round(float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": str(row['Entity']),
                "metric": "share",
                "period": "TW",
                "value": round(float(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })

    # ---------- TOP 3 WoW GAINERS / DECLINERS ----------
    wow_df = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False)
    gainers = wow_df.head(3)
    decliners = wow_df.tail(3).sort_values('WoW_Pct', ascending=True)

    for _, row in gainers.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": round(float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    for _, row in decliners.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": round(float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
